--[[
        ════════════════════════════════════════════════════════════════
          AnsuHub — Sakura Ink กล่องเล็ก (ขนาดเท่า UI โปรปกติ)
        ════════════════════════════════════════════════════════════════
        • กล่องภาพหมึก + กลีบซากุระร่วง ขนาดกะทัดรัดกลางจอ — ไม่บังการเล่น
        • ลากย้ายได้ทั้งกล่อง (จับตรงไหนก็ได้) • ไม่มีโลโก้ ไม่มีแถบบน
        • แก้ขนาดกล่องได้ที่ SKINHUB.Width / SKINHUB.Height ด้านล่าง
        • ไม่มี: สกิน อาวุธ รีโมตเกม หรือโค้ดยุ่งกับเกมทั้งสิ้น
        • กด RightControl เพื่อซ่อน/แสดงกล่อง
]]

-- ════════════════════════════════════════════════════════════
--  ธีมซากุระอิงค์ (Sakura Ink) — แก้ค่าในตารางนี้ได้เลย
-- ════════════════════════════════════════════════════════════
local SKINHUB = {
        Width = 440,                 -- ความกว้างกล่อง (แก้เลขได้เลย)
        Height = 370,                -- ความสูงกล่อง
        CustomBackground = "",       -- ใส่ "rbxassetid://ไอดี" เพื่อใช้รูปของคุณเอง (ปล่อยว่าง = ภาพหมึกในตัว)
        Petals = true,               -- เอฟเฟกต์กลีบซากุระร่วง
        PetalCount = 14,             -- จำนวนกลีบซากุระ
}

local ToggleKeybind = Enum.KeyCode.RightControl

-- ภาพหมึกญี่ปุ่น + กลีบซากุระ (base64 จากสคริปต์เดิม)
local SKINHUB_BG_B64 = ""
local SKINHUB_PETAL_B64 = ""

-- ════════════════════════════════════════════════════════════
--  เซอร์วิสที่จำเป็นสำหรับ UI เท่านั้น
-- ════════════════════════════════════════════════════════════
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local RunService = game:GetService("RunService")
local HttpService = game:GetService("HttpService")

local LocalPlayer = Players.LocalPlayer

-- ที่ฝัง GUI ที่ปลอดภัย
local GuiParent = LocalPlayer and LocalPlayer:FindFirstChildOfClass("PlayerGui")
if not GuiParent then
        GuiParent = LocalPlayer:WaitForChild("PlayerGui")
end
pcall(function()
        if type(gethui) == "function" then
                GuiParent = gethui()
        end
end)

-- ════════════════════════════════════════════════════════════
--  โหลดภาพหมึก + กลีบซากุระจาก base64 ในตัว
--  (ถ้า executor ไม่รองรับ จะใช้ฉากหมึกวาดเองแทน — ไม่มีผลอะไร)
-- ════════════════════════════════════════════════════════════
local SakuraTheme = { Background = "", Petal = "" }

local function skin_b64(s)
        local ok, r = pcall(function()
                return base64_decode(s)
        end)
        if ok and type(r) == "string" and #r > 0 then
                return r
        end
        local ok2, r2 = pcall(function()
                return HttpService:Base64Decode(s)
        end)
        if ok2 and type(r2) == "string" then
                return r2
        end
        return ""
end

pcall(function()
        if SKINHUB.CustomBackground ~= "" then
                SakuraTheme.Background = SKINHUB.CustomBackground
                return
        end
        if not (writefile and getcustomasset) then
                return
        end
        local raw = skin_b64(SKINHUB_BG_B64)
        if #raw == 0 then
                return
        end
        local bg_file = "AnsuHub_bg.png"
        writefile(bg_file, raw)
        SakuraTheme.Background = getcustomasset(bg_file)
end)

pcall(function()
        if not (writefile and getcustomasset) then
                return
        end
        local praw = skin_b64(SKINHUB_PETAL_B64)
        if #praw == 0 then
                return
        end
        local petal_file = "AnsuHub_petal.png"
        writefile(petal_file, praw)
        SakuraTheme.Petal = getcustomasset(petal_file)
end)

-- ════════════════════════════════════════════════════════════
--  ScreenGui + กล่องเล็กกลางจอ (ขนาดเท่า UI โปรปกติ ไม่บังเกม)
-- ════════════════════════════════════════════════════════════
local ScreenGui = Instance.new("ScreenGui")
ScreenGui.Name = "AnsuHub_SakuraOnly"
ScreenGui.ResetOnSpawn = false
ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
ScreenGui.DisplayOrder = 999
ScreenGui.Parent = GuiParent

local BoxW = tonumber(SKINHUB.Width) or 440
local BoxH = tonumber(SKINHUB.Height) or 370
if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
        BoxW = math.floor(BoxW * 0.72)
        BoxH = math.floor(BoxH * 0.72)
end

local Root = Instance.new("Frame")
Root.Name = "SakuraRoot"
Root.AnchorPoint = Vector2.new(0.5, 0.5)
Root.Position = UDim2.fromScale(0.5, 0.5)
Root.Size = UDim2.fromOffset(BoxW, BoxH)
Root.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
Root.BorderSizePixel = 0
Root.Active = true
Root.ClipsDescendants = true
Root.Parent = ScreenGui

local RootCorner = Instance.new("UICorner")
RootCorner.CornerRadius = UDim.new(0, 8)
RootCorner.Parent = Root

local RootStroke = Instance.new("UIStroke")
RootStroke.Color = Color3.fromRGB(55, 55, 55)
RootStroke.Thickness = 1
RootStroke.Transparency = 0.35
RootStroke.Parent = Root

-- ════════════════════════════════════════════════════════════
--  ฉากหมึกวาดเอง (fallback) — ใช้เมื่อโหลดภาพไม่ได้
-- ════════════════════════════════════════════════════════════
local InkFallback = Instance.new("Frame")
InkFallback.Name = "InkFallback"
InkFallback.Size = UDim2.fromScale(1, 1)
InkFallback.BackgroundTransparency = 1
InkFallback.ClipsDescendants = true
InkFallback.ZIndex = 1
InkFallback.Parent = Root

local sky = Instance.new("Frame")
sky.Name = "InkSky"
sky.BorderSizePixel = 0
sky.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
sky.Size = UDim2.fromScale(1, 1)
sky.ZIndex = 1
sky.Parent = InkFallback

local skyGradient = Instance.new("UIGradient")
skyGradient.Rotation = 90
skyGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0.00, Color3.fromRGB(24, 23, 27)),
        ColorSequenceKeypoint.new(0.55, Color3.fromRGB(46, 41, 46)),
        ColorSequenceKeypoint.new(0.85, Color3.fromRGB(82, 69, 70)),
        ColorSequenceKeypoint.new(1.00, Color3.fromRGB(110, 92, 88)),
})
skyGradient.Parent = sky

local sun = Instance.new("Frame")
sun.Name = "InkSun"
sun.BorderSizePixel = 0
sun.BackgroundColor3 = Color3.fromRGB(190, 58, 52)
sun.BackgroundTransparency = 0.22
sun.Position = UDim2.new(1, -70, 0, 22)
sun.Size = UDim2.fromOffset(48, 48)
sun.ZIndex = 1
sun.Parent = InkFallback

local sunCorner = Instance.new("UICorner")
sunCorner.CornerRadius = UDim.new(1, 0)
sunCorner.Parent = sun

local function ink_hill(width, height, xpos, shade, alpha)
        local hill = Instance.new("Frame")
        hill.Name = "InkHill"
        hill.BorderSizePixel = 0
        hill.BackgroundColor3 = shade
        hill.BackgroundTransparency = alpha
        hill.AnchorPoint = Vector2.new(0, 1)
        hill.Position = UDim2.new(xpos, 0, 1, 24)
        hill.Size = UDim2.new(width, 0, 0, height)
        hill.ZIndex = 1
        hill.Parent = InkFallback

        local hillCorner = Instance.new("UICorner")
        hillCorner.CornerRadius = UDim.new(0, 34)
        hillCorner.Parent = hill
end
ink_hill(0.62, 64, -0.08, Color3.fromRGB(16, 15, 18), 0.25)
ink_hill(0.58, 48, 0.45, Color3.fromRGB(30, 26, 30), 0.45)
ink_hill(0.50, 36, 0.62, Color3.fromRGB(58, 48, 50), 0.62)

local topfade = Instance.new("Frame")
topfade.Name = "InkTopFade"
topfade.BorderSizePixel = 0
topfade.BackgroundColor3 = Color3.fromRGB(8, 8, 10)
topfade.Size = UDim2.new(1, 0, 0, 80)
topfade.ZIndex = 1
topfade.Parent = InkFallback

local topfadeGradient = Instance.new("UIGradient")
topfadeGradient.Rotation = 90
topfadeGradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0.25),
        NumberSequenceKeypoint.new(1, 1),
})
topfadeGradient.Parent = topfade

-- ภาพหมึกจริงจากสคริปต์เดิม (โหลดสำเร็จจะทับฉาก fallback)
local InkPaintingRef = nil
if SakuraTheme.Background ~= "" then
        local InkPainting = Instance.new("ImageLabel")
        InkPainting.Name = "InkPainting"
        InkPainting.BackgroundTransparency = 1
        InkPainting.Image = SakuraTheme.Background
        InkPainting.Size = UDim2.fromScale(1, 1)
        InkPainting.ScaleType = Enum.ScaleType.Stretch
        InkPainting.Active = true
        InkPainting.ZIndex = 2
        InkPainting.Parent = Root
        InkPaintingRef = InkPainting
end

-- ════════════════════════════════════════════════════════════
--  กลีบซากุระร่วงในกล่อง (เอฟเฟกต์ UI เท่านั้น — ไม่ยุ่งกับเกม)
-- ════════════════════════════════════════════════════════════
local OverlayRef = nil
if SKINHUB.Petals and SakuraTheme.Petal ~= "" then
        local Overlay = Instance.new("Frame")
        Overlay.Name = "PetalOverlay"
        Overlay.Size = UDim2.fromScale(1, 1)
        Overlay.BackgroundTransparency = 1
        Overlay.Active = true
        Overlay.ClipsDescendants = true
        Overlay.ZIndex = 50
        Overlay.Parent = Root
        OverlayRef = Overlay

        local rng = Random.new()
        local petals = {}

        for i = 1, math.max(1, SKINHUB.PetalCount) do
                local petal = Instance.new("ImageLabel")
                petal.Name = "Petal" .. i
                petal.BackgroundTransparency = 1
                petal.Image = SakuraTheme.Petal
                petal.ImageColor3 = Color3.fromRGB(255, rng:NextInteger(115, 175), rng:NextInteger(135, 185))
                petal.ImageTransparency = rng:NextNumber(0.2, 0.55)
                petal.Size = UDim2.fromOffset(rng:NextInteger(9, 15), rng:NextInteger(9, 15))
                petal.Rotation = 0
                petal.ZIndex = 50
                petal.Parent = Overlay

                petals[i] = {
                        obj = petal,
                        x = rng:NextNumber(0, 1),
                        y = rng:NextNumber(-0.2, 1),
                        speed = rng:NextNumber(0.04, 0.11),
                        sway = rng:NextNumber(0.012, 0.05),
                        phase = rng:NextNumber(0, math.pi * 2),
                        spin = rng:NextNumber(-70, 70),
                }
        end

        RunService.Heartbeat:Connect(function(dt)
                if not Overlay.Parent then
                        return
                end
                for _, s in ipairs(petals) do
                        s.y = s.y + s.speed * dt
                        s.phase = s.phase + dt * 1.6
                        if s.y > 1.06 then
                                s.y = -0.06
                                s.x = rng:NextNumber(0, 1)
                        end
                        local px = math.clamp(s.x + math.sin(s.phase) * s.sway, -0.02, 1.02)
                        s.obj.Position = UDim2.fromScale(px, s.y)
                        s.obj.Rotation = (s.obj.Rotation + s.spin * dt) % 360
                end
        end)
end

-- ════════════════════════════════════════════════════════════
--  ลากย้ายทั้งกล่อง (จับตรงไหนก็ได้) — UI เท่านั้น
-- ════════════════════════════════════════════════════════════
local Dragging = false
local DragStart = nil
local StartPosition = nil

local function hook_drag(gui)
        gui.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        Dragging = true
                        DragStart = input.Position
                        StartPosition = Root.Position
                end
        end)
end
hook_drag(Root)
if InkPaintingRef then
        hook_drag(InkPaintingRef)
end
if OverlayRef then
        hook_drag(OverlayRef)
end

UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                Dragging = false
        end
end)

UserInputService.InputChanged:Connect(function(input)
        if not Dragging then
                return
        end
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                local delta = input.Position - DragStart
                Root.Position = UDim2.new(
                        StartPosition.X.Scale,
                        StartPosition.X.Offset + delta.X,
                        StartPosition.Y.Scale,
                        StartPosition.Y.Offset + delta.Y
                )
        end
end)

-- ════════════════════════════════════════════════════════════
--  ซ่อน/แสดงกล่องด้วย RightControl
-- ════════════════════════════════════════════════════════════
UserInputService.InputBegan:Connect(function(input, processed)
        if processed then
                return
        end
        if input.KeyCode == ToggleKeybind then
                ScreenGui.Enabled = not ScreenGui.Enabled
        end
end)
